    Bug 1973642 - Override the global value of security.allow_eval_in_parent_process. r=freaktechnik
    This value was already true but the default value in StaticPrefList.yaml has now changed to false.

    Differential Revision: https://phabricator.services.mozilla.com/D254793

diff --git a/mail/app/profile/all-thunderbird.js b/mail/app/profile/all-thunderbird.js
index d370f4f6474..417524054e2 100644
--- a/mail/app/profile/all-thunderbird.js
+++ b/mail/app/profile/all-thunderbird.js
@@ -906,8 +906,8 @@ pref("privacy.webrtc.globalMuteToggles", false);
 // instead of space in the file name.
 pref("mail.save_msg_filename_underscores_for_space", false);

-// See bug 1572568 for details. Disallow eval() with system principal.
-pref("security.allow_eval_with_system_principal", false);
+// Necessary until we move off the Matrix JS SDK.
+pref("security.allow_eval_in_parent_process", true);

 // Enable FIDO U2F
 pref("security.webauth.u2f", true);
